api_examples:
TypeScript: import { CompatStream } from '@redwood/sdk/compat';
const s = new CompatStream(client.openStream(), { mode: 'compat-v1' });
for await (const chunk of s) { handle(chunk); }

Go: import "github.com/redwood/sdk/compat"
iter := compat.NewCompatIterator(client.ListItems(ctx), compat.ModeV1)
for iter.Next() { items := iter.Page(); process(items) }
